const choiceState={building:'all',floor:'all',max:30,rooms:'all',saved:false,compare:[]};
let savedApartments=[];
try { savedApartments=JSON.parse(localStorage.getItem('plan-saved')||'[]').filter(id=>apartments.some(a=>a.id===id)); } catch {}
apartments.forEach((a,i)=>{a.building=['a','a','b','c'][i];a.view=['Набережная','Набережная','Зелёный двор','Городская улица'][i];});
apartments[3].feature='Три спальни и общая кухня-гостиная';
const selectionFilters=document.createElement('div');selectionFilters.className='selection-filters';selectionFilters.innerHTML=`<label>Корпус<select id="choice-building"><option value="all">Все корпуса</option><option value="a">А · у воды</option><option value="b">Б · у двора</option><option value="c">В · у города</option></select></label><label>Этаж<select id="choice-floor"><option value="all">Любой этаж</option></select></label><label class="budget-filter">Бюджет до <output id="choice-max-output">30 млн ₽</output><input type="range" id="choice-max" min="10" max="30" step=".5" value="30"></label><label class="saved-filter"><input type="checkbox" id="choice-saved">Только избранное <span id="saved-number">0</span></label>`;document.querySelector('.apartment-controls').after(selectionFilters);
const comparison=document.createElement('section');comparison.className='apartment-comparison';comparison.id='apartment-comparison';comparison.hidden=true;comparison.setAttribute('aria-label','Сравнение квартир');grid.after(comparison);
const detail=document.createElement('dialog');detail.className='apartment-detail';detail.id='apartment-detail';detail.setAttribute('aria-labelledby','flat-detail-title');detail.innerHTML=`<button type="button" class="flat-close" aria-label="Закрыть планировку">Закрыть ×</button><div class="flat-drawing" id="flat-drawing"></div><div class="flat-reading"><span class="section-index" id="flat-detail-id"></span><h2 id="flat-detail-title"></h2><p id="flat-detail-feature"></p><dl id="flat-detail-facts"></dl><p class="flat-note">Эскизная схема без масштаба. Мебель показывает возможный сценарий; размеры и конструктив не являются рабочим проектом.</p><button type="button" class="button button-dark" id="flat-calculate">Рассчитать платёж</button><button type="button" class="flat-save" id="flat-save">В избранное</button></div>`;document.body.append(detail);
let activeFlat=apartments[0];
function updateFloors(){const floors=[...new Set(apartments.filter(a=>choiceState.building==='all'||a.building===choiceState.building).map(a=>a.floor))].sort((a,b)=>a-b);const el=document.querySelector('#choice-floor');el.innerHTML='<option value="all">Любой этаж</option>'+floors.map(f=>`<option value="${f}">${f} этаж</option>`).join('');choiceState.floor='all';}
function saveFlat(id){savedApartments=savedApartments.includes(id)?savedApartments.filter(x=>x!==id):[...savedApartments,id];try{localStorage.setItem('plan-saved',JSON.stringify(savedApartments));}catch{}renderSelection();if(detail.open)updateFlatSave();}
function renderSelection(){const visible=apartments.filter(a=>(choiceState.rooms==='all'||a.rooms===Number(choiceState.rooms))&&(choiceState.building==='all'||a.building===choiceState.building)&&(choiceState.floor==='all'||a.floor===Number(choiceState.floor))&&a.priceNumber<=choiceState.max*1e6&&(!choiceState.saved||savedApartments.includes(a.id)));grid.innerHTML=visible.length?visible.map(a=>`<article class="apartment-card"><div class="apartment-art">${enhancedPlan(a.plan)}<span class="flat-orientation">СХЕМА / СЕВЕР ↑</span><button class="save-flat" data-save="${a.id}" type="button" aria-pressed="${savedApartments.includes(a.id)}" aria-label="Сохранить квартиру ${a.id}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4Z"/></svg></button></div><div class="apartment-body"><span>Остров / корпус ${buildingInfo[a.building].letter} / ${a.id}</span><h3>${a.area} м²</h3><p>${a.rooms} ${a.rooms===1?'спальня':'спальни'} · ${a.floor} этаж<br>${a.view}</p><div class="apartment-bottom"><b>${a.price}</b><button type="button" data-flat="${a.id}">Планировка ↗</button></div><button class="compare-flat" type="button" data-compare="${a.id}" ${choiceState.compare.length===2&&!choiceState.compare.includes(a.id)?'disabled':''} aria-pressed="${choiceState.compare.includes(a.id)}">${choiceState.compare.includes(a.id)?'Убрать из сравнения':'Сравнить'}</button></div></article>`).join(''):`<div class="selection-empty"><h3>Пока нет такого сочетания.</h3><p>В эскизной коллекции четыре квартиры. Попробуйте другой корпус или бюджет.</p><button type="button" id="choice-reset">Сбросить фильтры</button></div>`;resultCount.textContent=`${visible.length} ${visible.length===1?'вариант':visible.length===0?'вариантов':'варианта'}`;document.querySelector('#saved-number').textContent=savedApartments.length;document.querySelector('#choice-reset')?.addEventListener('click',resetChoice);renderComparison();}
function resetChoice(){Object.assign(choiceState,{building:'all',floor:'all',max:30,rooms:'all',saved:false});document.querySelector('#choice-building').value='all';document.querySelector('#choice-max').value=30;document.querySelector('#choice-max-output').textContent='30 млн ₽';document.querySelector('#choice-saved').checked=false;filterButtons.forEach(b=>{b.classList.toggle('active',b.dataset.filter==='all');b.setAttribute('aria-pressed',String(b.dataset.filter==='all'));});updateFloors();renderSelection();}
function renderComparison(){comparison.hidden=choiceState.compare.length===0;if(comparison.hidden)return;const chosen=apartments.filter(a=>choiceState.compare.includes(a.id));comparison.innerHTML=`<div class="comparison-heading"><h3>Рядом — проще выбрать.</h3><button type="button" id="clear-comparison">Очистить сравнение</button></div>${chosen.length===1?'<p>Выберите ещё одну квартиру, чтобы сравнить два варианта.</p>':''}<div class="comparison-grid">${chosen.map(a=>`<article><div class="comparison-plan">${enhancedPlan(a.plan)}</div><strong>${a.area} м²</strong><dl><div><dt>Спальни</dt><dd>${a.rooms}</dd></div><div><dt>Корпус / этаж</dt><dd>${buildingInfo[a.building].letter} / ${a.floor}</dd></div><div><dt>Окружение</dt><dd>${a.view}</dd></div><div><dt>Цена</dt><dd>${a.price}</dd></div></dl><button type="button" data-flat="${a.id}">Открыть планировку ↗</button></article>`).join('')}</div><p class="compare-status" role="status">${chosen.length===2?'Выбраны два варианта. Уберите один, чтобы заменить его.':''}</p>`;document.querySelector('#clear-comparison').addEventListener('click',()=>{choiceState.compare=[];renderSelection();});}
function updateFlatSave(){document.querySelector('#flat-save').textContent=savedApartments.includes(activeFlat.id)?'Сохранено · убрать':'В избранное';document.querySelector('#flat-save').setAttribute('aria-pressed',String(savedApartments.includes(activeFlat.id)));}
function showFlat(id){activeFlat=apartments.find(a=>a.id===id);const a=activeFlat;document.querySelector('#flat-drawing').innerHTML=enhancedPlan(a.plan);document.querySelector('#flat-detail-id').textContent=`ОСТРОВ / КОРПУС ${buildingInfo[a.building].letter} / ${a.id}`;document.querySelector('#flat-detail-title').textContent=`${a.area} м²`;document.querySelector('#flat-detail-feature').textContent=a.feature;document.querySelector('#flat-detail-facts').innerHTML=[['Спальни',a.rooms],['Этаж',a.floor],['Окружение',a.view],['Цена',a.price]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('');updateFlatSave();detail.showModal();document.body.classList.add('modal-open');}
document.querySelector('#flat-save').addEventListener('click',()=>saveFlat(activeFlat.id));detail.querySelector('.flat-close').addEventListener('click',()=>detail.close());detail.addEventListener('close',()=>document.body.classList.remove('modal-open'));
document.addEventListener('click',event=>{const button=event.target.closest('[data-flat],[data-save],[data-compare]');if(!button)return;if(button.dataset.flat)showFlat(button.dataset.flat);if(button.dataset.save)saveFlat(button.dataset.save);if(button.dataset.compare){const id=button.dataset.compare;choiceState.compare=choiceState.compare.includes(id)?choiceState.compare.filter(x=>x!==id):choiceState.compare.length<2?[...choiceState.compare,id]:[choiceState.compare[1],id];renderSelection();}});
filterButtons.forEach(button=>button.addEventListener('click',()=>{choiceState.rooms=button.dataset.filter;renderSelection();}));
document.querySelector('#choice-building').addEventListener('change',event=>{choiceState.building=event.target.value;updateFloors();renderSelection();});document.querySelector('#choice-floor').addEventListener('change',event=>{choiceState.floor=event.target.value;renderSelection();});document.querySelector('#choice-max').addEventListener('input',event=>{choiceState.max=Number(event.target.value);document.querySelector('#choice-max-output').textContent=`${String(choiceState.max).replace('.',',')} млн ₽`;renderSelection();});document.querySelector('#choice-saved').addEventListener('change',event=>{choiceState.saved=event.target.checked;renderSelection();});
const floorSection=document.createElement('div');floorSection.className='building-selection';floorSection.innerHTML='<span>ВЫБОР В ЭТОМ КОРПУСЕ</span><div id="building-floor-buttons"></div><a href="#apartments" id="building-select-flats">Открыть квартиры корпуса А ↗</a>';document.querySelector('.building-detail').append(floorSection);document.querySelector('.building-detail>.inline-link').hidden=true;
let selectedBuilding='a';function showBuildingFloors(){const list=apartments.filter(a=>a.building===selectedBuilding);document.querySelector('#building-floor-buttons').innerHTML=list.map(a=>`<button type="button" data-building-flat="${a.id}">${a.floor}<small>этаж · ${a.area} м²</small></button>`).join('');document.querySelector('#building-select-flats').textContent=`Открыть квартиры корпуса ${buildingInfo[selectedBuilding].letter} ↗`;floorSection.querySelectorAll('[data-building-flat]').forEach(b=>b.addEventListener('click',()=>showFlat(b.dataset.buildingFlat)));}
document.querySelectorAll('.building').forEach(b=>b.addEventListener('click',()=>{selectedBuilding=b.dataset.building;showBuildingFloors();}));document.querySelector('#building-select-flats').addEventListener('click',()=>{choiceState.building=selectedBuilding;choiceState.rooms='all';choiceState.max=30;choiceState.saved=false;document.querySelector('#choice-building').value=selectedBuilding;document.querySelector('#choice-max').value=30;document.querySelector('#choice-max-output').textContent='30 млн ₽';document.querySelector('#choice-saved').checked=false;filterButtons.forEach(b=>{b.classList.toggle('active',b.dataset.filter==='all');b.setAttribute('aria-pressed',String(b.dataset.filter==='all'));});updateFloors();renderSelection();});
const financeChoice=document.createElement('label');financeChoice.className='finance-choice';financeChoice.innerHTML=`Квартира для расчёта<select id="finance-flat">${apartments.map(a=>`<option value="${a.id}">${a.id} · ${a.area} м² · ${a.price}</option>`).join('')}</select>`;document.querySelector('.calc-top').after(financeChoice);
function selectionPayment(){const a=apartments.find(a=>a.id===document.querySelector('#finance-flat').value);const downFraction=Number(down.value)/100;const principal=a.priceNumber*(1-downFraction);const rate=.12/12;const periods=Number(years.value)*12;document.querySelector('.calc-top strong').textContent=a.price;document.querySelector('#down-output').textContent=formatMoney(a.priceNumber*downFraction);document.querySelector('#monthly-payment').textContent=formatMoney(Math.round(principal*rate/(1-Math.pow(1+rate,-periods))));}
document.querySelector('#finance-flat').addEventListener('change',selectionPayment);[down,years].forEach(i=>i.addEventListener('input',selectionPayment));document.querySelector('#flat-calculate').addEventListener('click',()=>{document.querySelector('#finance-flat').value=activeFlat.id;selectionPayment();detail.close();document.querySelector('#purchase').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});});
updateFloors();renderSelection();showBuildingFloors();selectionPayment();
